            let loaded = false;
            let lastError;
            for (let attempt = 0; attempt <= MAX_RETRIES && !loaded; attempt += 1) {
                if (attempt > 0) await sleep(Math.min(input.timeout, 1_000 * 2 ** attempt));
                try {
                    await beforeRequest(page);
                    await navigatePage(page, input.startUrl, input.timeout);
                    loaded = true;
                } catch (error) {
                    lastError = error;
                }
